import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Swal from 'sweetalert2';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'datatables.net-bs5/css/dataTables.bootstrap5.min.css';
import $ from 'jquery';
import 'datatables.net-bs5';
import config from './config'; // Importa el archivo de configuración

const App = () => {
  const [gestiones, setGestiones] = useState([]);
  const [idUsuario, setIdUsuario] = useState(null);
  const [idCampana, setIdCampana] = useState(null);

  const handleTokenError = () => {
    localStorage.removeItem('token');
    Swal.fire('Error', 'No estás autenticado. Por favor, inicia sesión.', 'error').then(() => {
      window.location.href = '/';
    });
  };

  const getToken = () => {
    const token = localStorage.getItem('token');
    if (!token) {
      handleTokenError();
      throw new Error('Token no disponible.');
    }
    return token;
  };

  const getUrlParams = async () => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get('id');
    const campana = params.get('campana');

    if (!id || !campana) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'Faltan parámetros en la URL.'
      });
      throw new Error('Faltan parámetros en la URL.');
    }

    try {
      const decryptedId = await decrypt(id);
      const decryptedCampana = await decrypt(campana);
      setIdUsuario(decryptedId);
      setIdCampana(decryptedCampana);
    } catch (error) {
      console.error('Error al desencriptar parámetros:', error.message);
    }
  };

  const decrypt = async (value) => {
    if (!value || value.trim() === '') {
      throw new Error('El valor encriptado está vacío o es inválido.');
    }

    const token = getToken();
    const response = await fetch(`${config.API_BASE_URL}/decrypt`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ encrypted_value: value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al desencriptar: ${errorText}`);
    }

    const data = await response.json();
    if (!data.decrypted_value) {
      throw new Error('La API no devolvió un valor desencriptado.');
    }

    return data.decrypted_value;
  };

  const encryptWithAPI = async (value) => {
    if (!value || value.trim() === '') {
      Swal.fire({
        icon: 'error',
        title: 'Error de Encriptado',
        text: 'El valor a encriptar está vacío.'
      });
      throw new Error('El valor a encriptar está vacío.');
    }

    const token = getToken();
    const response = await fetch(`${config.API_BASE_URL}/encrypt`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al encriptar: ${errorText}`);
    }

    const data = await response.json();
    return data.encrypted_value;
  };

  const loadTable = async () => {
    try {
      const token = getToken();
      const response = await axios.post(`${config.API_BASE_URL}/gestiones`, {
        opcion: 7,
        id_usuario: idUsuario,
        id_campana: idCampana
      }, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setGestiones(response.data);
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No se pudo cargar la tabla de gestiones.'
      });
      console.error('Error al cargar datos:', error.message);
    }
  };

  const handleBackClick = async () => {
    try {
      const encryptedId = await encryptWithAPI(idUsuario);
      const encryptedCampana = await encryptWithAPI(idCampana);
      window.location.href = `modulos?id=${encryptedId}&campana=${encryptedCampana}`;
    } catch (error) {
      console.error(error.message);
    }
  };

  useEffect(() => {
    const initialize = async () => {
      try {
        await getUrlParams(); // Obtiene los parámetros y establece el estado
      } catch (error) {
        console.error('Error al obtener parámetros:', error.message);
      }
    };

    initialize();
  }, []);

  useEffect(() => {
    if (idUsuario && idCampana) {
      loadTable();
    }
  }, [idUsuario, idCampana]);

  useEffect(() => {
    if (gestiones.length > 0) {
      $('#gestionesTable').DataTable();
    }
  }, [gestiones]);

  return (
    <div className="container mt-5">
      <div className="card">
        <div className="card-header text-center">
          <h4>Gestiones</h4>
        </div>
        <div className="card-body">
          <table className="table table-striped" id="gestionesTable">
            <thead>
              <tr>
                <th scope="col">ID Gestión</th>
                <th scope="col">Nombre</th>
                <th scope="col">DPI</th>
              </tr>
            </thead>
            <tbody>
              {gestiones.map((gestion) => (
                <tr key={gestion.ID_GESTIONES} onClick={async () => {
                  const encryptedIdGestion = await encryptWithAPI(gestion.ID_GESTIONES);
                  const encryptedId = await encryptWithAPI(idUsuario);
                  const encryptedIdCampana = await encryptWithAPI(idCampana);
                  window.location.href = `detalle_gestion?id_gestion=${encryptedIdGestion}&id=${encryptedId}&campana=${encryptedIdCampana}`;
                }}>
                  <td>{gestion.ID_GESTIONES}</td>
                  <td>{gestion.NOMBRE}</td>
                  <td>{gestion.DPI}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <button id="backButton" className="btn btn-secondary mt-3" onClick={handleBackClick}>
            Regresar
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;
